@privylabs/authorized/contracts/Authoriz.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.17;

import { IAuthorized } from "./interfaces/IAuthorized.sol";

abstract contract Authorized is IAuthorized {
    constructor() {
        /// @notice Add the deployer as an authorized admin
        owner = msg.sender;
    }

    /// @notice the owner of the contract
    address private owner;

    /// @notice A mapping storing authorized admins
    /// @dev admin address => authorized status
    mapping (address => bool) private authorizedAdmins;

    /// @notice A mapping of the authorized delegate operators
    /// @dev operator address => authorized status
    mapping (address => bool) private authorizedOperators;

    /// @notice Modifier to ensure caller is owner
    modifier onlyOwner() {
        if (msg.sender != owner) {
            revert Unauthorized();
        }
        _;
    }

    /// @dev Modifier to ensure caller is authorized admin
    modifier onlyAuthorizedAdmin() {
        if (msg.sender != owner && !authorizedAdmins[msg.sender]) {
            revert Unauthorized();
        }
        _;
    }

    /// @dev Modifier to ensure caller is authorized operator
    modifier onlyAuthorizedOperator() {
        if (msg.sender != owner && !authorizedAdmins[msg.sender] && !authorizedOperators[msg.sender]) {
            revert Unauthorized();
        }
        _;
    }

    /// @inheritdoc IAuthorized
    function transferOwnership(address newOwner) external onlyOwner {
        /// check if address is not null
        require(newOwner != address(0), "Authorized System: New owner cannot be null");
        /// check if address is not the same as owner
        require(newOwner != owner, "Authorized System: New owner cannot be the same as old owner");
        /// check if address is not the same as operator
        require(!authorizedOperators[owner], "Authorized System: Owner cannot be an operator");

        /// update the owner
        owner = newOwner;
    }

    /// @inheritdoc IAuthorized
    function setAuthorizedAdmin(address _admin, bool status) public virtual onlyAuthorizedAdmin {
        /// check if address is not null
        require(_admin != address(0), "Authorized System: Admin address cannot be null");
        /// check if address is not the same as operator
        require(!authorizedOperators[_admin], "Authorized System: Admin cannot be an operator");

        /// update the admin status
        authorizedAdmins[_admin] = status;
        emit SetAdmin(_admin);
    }

    /// @inheritdoc IAuthorized
    function setAuthorizedOperator(address _operator, bool status) public virtual onlyAuthorizedAdmin {
        /// check if address is not null
        require(_operator != address(0), "Authorized System: Operator address cannot be null");
        /// check if address is not the same as admin
        require(!authorizedAdmins[_operator], "Authorized System: Operator cannot be an admin");

        /// update the operator status
        authorizedOperators[_operator] = status;
        emit SetOperator(_operator);
    }

    /// @inheritdoc IAuthorized
    function getAuthorizedAdmin(address _admin) public view virtual returns (bool) {
        return authorizedAdmins[_admin];
    }

    /// @inheritdoc IAuthorized
    function getAuthorizedOperator(address _operator) public view virtual returns (bool) {
        return authorizedOperators[_operator];
    }

    /// @inheritdoc IAuthorized
    function getOwner() public view virtual override returns (address) {
        return owner;
    }
}

@privylabs/authorized/contracts/interfac.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.17;

interface IAuthorized {

    /// @notice Generic error when a user attempts to access a feature/function without proper access
    error Unauthorized();

    /// @notice Event emitted when a new admin is added
    event SetAdmin(address indexed admin);

    /// @notice Event emitted when a new operator is added
    event SetOperator(address indexed operator);

    /// @notice Event emmited when a new authOperator is added
    event SetAuthOperator(address indexed authOperator);

    /// @notice Transfer ownership of the contract to a new account (`newOwner`).
    /// @param newOwner The address to transfer ownership to.
    function transferOwnership(address newOwner) external;

    /// @notice Add an authorized admin
    /// @param _admin address of the admin
    /// @param status status of the admin
    function setAuthorizedAdmin(address _admin, bool status) external;

    /// @notice Add an authorized Operator
    /// @param _operator address of the operator
    /// @param status status of the operator
    function setAuthorizedOperator(address _operator, bool status) external;

    /// @notice Get the status of an admin
    /// @param _admin address of the admin
    /// @return status of the admin
    function getAuthorizedAdmin(address _admin) external view returns (bool);

    /// @notice Get the status of an operator
    /// @param _operator address of the operator
    /// @return status of the operator
    function getAuthorizedOperator(address _operator) external view returns (bool);

    /// @notice Get the owner
    function getOwner() external view returns (address);
}

contracts/BillNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";

contract BillNFT is ERC721 {
    // Events for NFT operations
    event NFTMinted(uint256 indexed tokenId, address indexed to);

    constructor(
        string memory _name,
        string memory _symbol
    ) ERC721(_name, _symbol) {}

    function _mintBillNFT(address to, uint256 tokenId) internal {
        _safeMint(to, tokenId);
        emit NFTMinted(tokenId, to);
    }

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal virtual override returns (address) {
        return super._update(to, tokenId, auth);
    }

    function getNFTOwner(uint256 tokenId) external view returns (address) {
        require(_ownerOf(tokenId) != address(0), "NFT does not exist");
        return ownerOf(tokenId);
    }
}

contracts/FactoringContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {Authorized} from "@privylabs/authorized/contracts/Authorized.sol";
import {UintArrayManager} from "@aurelianoa/array-manager/contracts/UintArrayManager.sol";
import {BillNFT} from "./BillNFT.sol";

/**
 * @title FactoringContract
 * @dev Smart contract for factoring finance with USDC/USDT
 *
 * Key Features:
 * - Receives funds and allocates into bills
 * - Each bill is represented as an NFT (ERC721 token) via BillNFT inheritance
 * - Funds are paid to the current NFT owner (transferable ownership)
 * - Configurable fee structure per bill via Conditions struct
 * - Default conditions: 5% fees, 80% upfront, 15% to NFT owner on completion
 * - Custom conditions can be set per bill for flexible terms
 * - When bill is paid, distributes funds according to bill's conditions to current NFT owner
 */
contract FactoringContract is
    BillNFT,
    ReentrancyGuard,
    Pausable,
    Authorized,
    UintArrayManager
{
    using SafeERC20 for IERC20;

    // Supported stablecoins
    IERC20 public immutable USDC;
    IERC20 public immutable USDT;

    // Constants
    uint256 public constant BASIS_POINTS = 10_000; /// 100 * 100 basis points = 100%
    uint256 public debtorFeePercentage = 40; // 0.4% debtor fee
    uint256 public lenderFeePercentage = 10; // 0.1% lender fee
    uint256 public numberofDaysPerMonth = 30;

    // Default conditions
    // @notice this is calculated on 100 basis points
    Conditions public defaultConditions =
        Conditions({
            upfrontPercentage: 8_000, // 80% paid upfront
            rateInterest: 200 // 2% Interest rate for the bill (monthly 30/360 days)
        });

    // Conditions structure for customizable fees per bill
    struct Conditions {
        uint256 upfrontPercentage; // Percentage paid upfront to bill owner
        uint256 rateInterest; // Interest rate for the bill (monthly 30/360 days)
    }

    // State variables
    uint256 private _nextBillId;
    uint256 public totalPoolBalance;
    mapping(address => uint256) public poolBalances; // USDC/USDT balances

    // BillRequest structure (created by debtor)
    struct BillRequest {
        uint256 id;
        address debtor;
        uint256 totalAmount;
        uint256 dueDate;
        BillRequestStatus status;
    }

    enum BillRequestStatus {
        Open, // Available for offers
        Accepted, // Offer accepted, bill created
        Cancelled // Cancelled by debtor
    }

    // Offer structure (created by lenders)
    struct Offer {
        uint256 id;
        uint256 billRequestId;
        address lender;
        address stablecoin; // USDC or USDT chosen by lender
        Conditions conditions;
        uint256 debtorFeePercentage;
        uint256 lenderFeePercentage;
        uint256 depositedAmount; // Amount deposited by lender
        OfferStatus status;
    }

    enum OfferStatus {
        Active,
        Accepted,
        Withdrawn,
        Expired
    }

    // Bill structure (created when offer is accepted)
    struct Bill {
        uint256 id; // Same as billRequestId and NFT tokenId
        address debtor;
        address lender;
        address stablecoin;
        uint256 totalAmount;
        uint256 upfrontPaid;
        uint256 startDate;
        uint256 dueDate;
        BillStatus status;
        Conditions conditions;
        uint256 debtorFeePercentage;
        uint256 lenderFeePercentage;
        uint256 acceptedOfferId;
    }

    enum BillStatus {
        Active, // Bill is active, debtor received upfront payment
        Completed, // Bill completed, all payments made
        Defaulted // Bill defaulted
    }

    // Counters
    uint256 private _nextOfferId;

    // Mappings
    mapping(uint256 => BillRequest) public billRequests;
    mapping(uint256 => Offer) public offers;
    mapping(uint256 => Bill) public bills;
    mapping(address => uint256[]) public ownerBills;
    mapping(uint256 => uint256[]) public billRequestOffers; // billRequestId => offerIds[]

    // Events
    event BillRequestCreated(
        uint256 indexed billRequestId,
        address indexed debtor,
        uint256 amount,
        address stablecoin
    );
    event OfferCreated(
        uint256 indexed offerId,
        uint256 indexed billRequestId,
        address indexed lender,
        uint256 upfrontAmount
    );
    event OfferAccepted(
        uint256 indexed offerId,
        uint256 indexed billRequestId,
        address indexed debtor,
        address lender
    );
    event BillCreated(
        uint256 indexed billId,
        address indexed debtor,
        address indexed lender,
        uint256 amount,
        address stablecoin
    );
    event BillCompleted(uint256 indexed billId, uint256 finalAmount);
    event BillNFTBurned(uint256 indexed billId, address indexed lastOwner);
    event PoolDeposit(
        address indexed depositor,
        uint256 amount,
        address stablecoin
    );
    event PoolWithdraw(
        address indexed withdrawer,
        uint256 amount,
        address stablecoin
    );
    event FeesCollected(uint256 amount, address stablecoin);
    event DefaultConditionsUpdated(
        uint256 upfrontPercentage,
        uint256 rateInterest
    );
    event BillRequestCancelled(uint256 indexed billRequestId);
    event OfferWithdrawn(uint256 indexed offerId, address indexed lender);

    constructor(
        address _usdc,
        address _usdt
    ) BillNFT("FactoringBill", "FBILL") {
        require(_usdc != address(0), "Invalid USDC address");
        require(_usdt != address(0), "Invalid USDT address");

        USDC = IERC20(_usdc);
        USDT = IERC20(_usdt);
        _nextBillId = 1;
        _nextOfferId = 1;
    }

    /**
     * @dev Set default conditions for new bills (only owner)
     * @param _upfrontPercentage Percentage paid upfront to bill owner
     * @param _rateInterest Interest rate for the bill
     */
    function setDefaultConditions(
        uint256 _upfrontPercentage,
        uint256 _rateInterest
    ) external onlyOwner {
        require(
            _upfrontPercentage > 0,
            "All percentages must be greater than 0"
        );

        defaultConditions = Conditions({
            upfrontPercentage: _upfrontPercentage,
            rateInterest: _rateInterest
        });

        emit DefaultConditionsUpdated(_upfrontPercentage, _rateInterest);
    }

    /**
     * @dev Set debtor fee percentage (only authorized admin)
     * @param _fee Fee percentage to set
     */
    function setDebtorFee(uint256 _fee) external onlyOwner {
        require(_fee > 0, "Fee must be greater than 0");
        debtorFeePercentage = _fee;
    }

    /**
     * @dev Set lender fee percentage (only authorized admin)
     * @param _fee Fee percentage to set
     */
    function setLenderFee(uint256 _fee) external onlyOwner {
        require(_fee > 0, "Fee must be greater than 0");
        lenderFeePercentage = _fee;
    }

    function setNumberOfDaysPerMonth(uint256 _days) external onlyOwner {
        require(_days > 0, "Days must be greater than 0");
        numberofDaysPerMonth = _days;
    }

    /**
     * @dev Create a new bill request (debtor creates this)
     * @param totalAmount Total amount of the bill
     * @param dueDate Due date of the bill (timestamp)
     */
    function createBillRequest(
        uint256 totalAmount,
        uint256 dueDate
    ) external nonReentrant whenNotPaused returns (uint256) {
        require(totalAmount > 0, "Amount must be greater than 0");
        require(dueDate > block.timestamp, "Due date must be in the future");

        uint256 billRequestId = _nextBillId++;

        // Create bill request
        billRequests[billRequestId] = BillRequest({
            id: billRequestId,
            debtor: msg.sender,
            totalAmount: totalAmount,
            dueDate: dueDate,
            status: BillRequestStatus.Open
        });

        // Mint NFT to debtor (bill request creator)
        _mintBillNFT(msg.sender, billRequestId);

        // Add to owner bills
        UintArrayManager.addToArray(ownerBills[msg.sender], billRequestId);

        emit BillRequestCreated(
            billRequestId,
            msg.sender,
            totalAmount,
            address(0) // No stablecoin specified at request time
        );

        return billRequestId;
    }

    /**
     * @dev Create an offer for a bill request (lender creates this)
     * @param billRequestId ID of the bill request
     * @param stablecoin Address of stablecoin (USDC or USDT) chosen by lender
     * @param conditions Conditions offered by the lender
     */
    function createOffer(
        uint256 billRequestId,
        address stablecoin,
        Conditions memory conditions
    ) external nonReentrant whenNotPaused returns (uint256) {
        BillRequest storage billRequest = billRequests[billRequestId];
        require(billRequest.id != 0, "Bill request does not exist");
        require(
            billRequest.status == BillRequestStatus.Open,
            "Bill request not open"
        );
        require(
            stablecoin == address(USDC) || stablecoin == address(USDT),
            "Unsupported stablecoin"
        );
        require(
            conditions.upfrontPercentage <= BASIS_POINTS,
            "Invalid conditions: sum cannot exceed 100%"
        );
        require(
            conditions.upfrontPercentage > 0,
            "All condition percentages must be greater than 0"
        );

        uint256 offerId = _nextOfferId++;
        uint256 upfrontAmount = (billRequest.totalAmount *
            conditions.upfrontPercentage) / BASIS_POINTS;

        // Transfer upfront amount from lender to contract
        IERC20(stablecoin).safeTransferFrom(
            msg.sender,
            address(this),
            upfrontAmount
        );

        // Create offer
        offers[offerId] = Offer({
            id: offerId,
            billRequestId: billRequestId,
            lender: msg.sender,
            stablecoin: stablecoin,
            conditions: conditions,
            debtorFeePercentage: debtorFeePercentage,
            lenderFeePercentage: lenderFeePercentage,
            depositedAmount: upfrontAmount,
            status: OfferStatus.Active
        });

        // Add offer to bill request's offers
        UintArrayManager.addToArray(billRequestOffers[billRequestId], offerId);

        emit OfferCreated(offerId, billRequestId, msg.sender, upfrontAmount);

        return offerId;
    }

    /**
     * @dev Accept an offer (NFT owner/debtor accepts this)
     * @param offerId ID of the offer to accept
     */
    function acceptOffer(uint256 offerId) external nonReentrant whenNotPaused {
        Offer storage offer = offers[offerId];
        require(offer.id != 0, "Offer does not exist");
        require(offer.status == OfferStatus.Active, "Offer not active");

        BillRequest storage billRequest = billRequests[offer.billRequestId];
        require(
            billRequest.status == BillRequestStatus.Open,
            "Bill request not open"
        );

        // Only NFT owner (debtor) can accept offers
        require(
            ownerOf(offer.billRequestId) == msg.sender,
            "Only NFT owner can accept offers"
        );
        /// calculate the debtor fee
        uint256 fees = (offer.debtorFeePercentage * offer.depositedAmount) /
            BASIS_POINTS;
        /// register the debtorFee on the pool balance
        // Keep fees in contract
        poolBalances[offer.stablecoin] += fees;
        totalPoolBalance += fees;
        /// the amount to be transfered must be depositedAmount - fee
        uint256 amountToTransfer = offer.depositedAmount - fees;

        // Update owner bills mapping
        UintArrayManager.removeFromArray(
            ownerBills[msg.sender],
            offer.billRequestId
        );
        UintArrayManager.addToArray(
            ownerBills[offer.lender],
            offer.billRequestId
        );

        // Create the actual bill
        bills[offer.billRequestId] = Bill({
            id: offer.billRequestId,
            debtor: msg.sender,
            lender: offer.lender,
            stablecoin: offer.stablecoin, // Use stablecoin from accepted offer
            totalAmount: billRequest.totalAmount,
            upfrontPaid: offer.depositedAmount,
            startDate: block.timestamp,
            dueDate: billRequest.dueDate,
            status: BillStatus.Active,
            conditions: offer.conditions,
            debtorFeePercentage: offer.debtorFeePercentage,
            lenderFeePercentage: offer.lenderFeePercentage,
            acceptedOfferId: offerId
        });

        // Update statuses
        offer.status = OfferStatus.Accepted;
        billRequest.status = BillRequestStatus.Accepted;

        // Transfer upfront amount to debtor using stablecoin from offer
        IERC20(offer.stablecoin).safeTransfer(msg.sender, amountToTransfer);
        // Transfer NFT from debtor to lender
        _transfer(msg.sender, offer.lender, offer.billRequestId);

        // Refund other active offers for this bill request
        _refundOtherOffers(offer.billRequestId, offerId);

        emit OfferAccepted(
            offerId,
            offer.billRequestId,
            msg.sender,
            offer.lender
        );
        emit BillCreated(
            offer.billRequestId,
            msg.sender,
            offer.lender,
            billRequest.totalAmount,
            offer.stablecoin // Use stablecoin from accepted offer
        );
    }

    /**
     * @dev Internal function to refund other active offers when one is accepted
     * @param billRequestId ID of the bill request
     * @param acceptedOfferId ID of the accepted offer (to skip)
     */
    function _refundOtherOffers(
        uint256 billRequestId,
        uint256 acceptedOfferId
    ) internal {
        uint256[] memory offerIds = billRequestOffers[billRequestId];
        for (uint256 i = 0; i < offerIds.length; i++) {
            uint256 offerId = offerIds[i];
            if (offerId != acceptedOfferId) {
                Offer storage offer = offers[offerId];
                if (offer.status == OfferStatus.Active) {
                    // Refund the lender using the stablecoin from the offer
                    IERC20(offer.stablecoin).safeTransfer(
                        offer.lender,
                        offer.depositedAmount
                    );
                    offer.status = OfferStatus.Expired;
                }
            }
        }
    }

    /**
     * @dev Complete bill payment (when bill is paid by debtor)
     * @param billId ID of the bill to complete
     */
    function completeBill(
        uint256 billId
    ) external payable nonReentrant whenNotPaused {
        Bill storage bill = bills[billId];
        require(bill.id != 0, "Bill does not exist");
        require(bill.status == BillStatus.Active, "Bill not active");

        uint256 totalPayment = bill.totalAmount;

        // Transfer total payment from debtor
        IERC20(bill.stablecoin).safeTransferFrom(
            msg.sender,
            address(this),
            totalPayment
        );

        // Get current NFT owner (should be the lender)
        address currentOwner = ownerOf(billId);
        uint256 fees = (bill.upfrontPaid * bill.lenderFeePercentage) /
            BASIS_POINTS; // Fees based on bill conditions
        // Keep fees in contract
        poolBalances[bill.stablecoin] += fees;
        totalPoolBalance += fees;
        /// days passed: get the days passed since startDate until now
        // Get the number of days passed since startDate until now
        uint256 daysPassed = (block.timestamp - bill.startDate) / 1 days;
        // calculate the interest based on the conditions from the startDate until now (in days 30)
        uint256 interest = (bill.upfrontPaid * bill.conditions.rateInterest * daysPassed) /
            numberofDaysPerMonth / BASIS_POINTS; // Interest based on bill conditions
        // Calculate distributions using bill's conditions
        uint256 ownerPayment = bill.upfrontPaid + interest - fees;
        uint256 debtorPayment = totalPayment - ownerPayment;

        // Pay current NFT owner the completion percentage + upfront paid
        if(ownerPayment > totalPayment) {
            ownerPayment = totalPayment - fees; // Ensure ownerPayment does not exceed totalPayment
        } 
        IERC20(bill.stablecoin).safeTransfer(currentOwner, ownerPayment);
        // Pay debtor the remaining amount (if any)
        if (debtorPayment > 0) {
            IERC20(bill.stablecoin).safeTransfer(bill.debtor, debtorPayment);
        }

        // Burn NFT but keep bill history in ownerBills
        _burn(billId);

        // Update bill status
        bill.status = BillStatus.Completed;

        emit BillCompleted(billId, totalPayment);
        emit BillNFTBurned(billId, currentOwner);
        emit FeesCollected(fees, bill.stablecoin);
    }

    /**
     * @dev Mark bill as defaulted (only authorized admin can call this)
     * @param billId ID of the bill to mark as defaulted
     */
    function markBillDefaulted(uint256 billId) external onlyAuthorizedAdmin {
        Bill storage bill = bills[billId];
        require(bill.id != 0, "Bill does not exist");
        require(bill.status == BillStatus.Active, "Bill not active");
        require(block.timestamp > bill.dueDate, "Bill not yet due");

        bill.status = BillStatus.Defaulted;
    }

    /**
     * @dev Cancel a bill request (only debtor can call this)
     * @param billRequestId ID of the bill request to cancel
     */
    function cancelBillRequest(uint256 billRequestId) external nonReentrant {
        BillRequest storage billRequest = billRequests[billRequestId];
        require(billRequest.id != 0, "Bill request does not exist");
        require(
            billRequest.status == BillRequestStatus.Open,
            "Bill request not open"
        );
        require(
            ownerOf(billRequestId) == msg.sender,
            "Only NFT owner can cancel"
        );

        billRequest.status = BillRequestStatus.Cancelled;

        // Refund all active offers
        _refundAllOffers(billRequestId);

        emit BillRequestCancelled(billRequestId);
    }

    /**
     * @dev Withdraw an offer (only lender can call this)
     * @param offerId ID of the offer to withdraw
     */
    function withdrawOffer(uint256 offerId) external nonReentrant {
        Offer storage offer = offers[offerId];
        require(offer.id != 0, "Offer does not exist");
        require(offer.status == OfferStatus.Active, "Offer not active");
        require(offer.lender == msg.sender, "Only lender can withdraw offer");

        // Refund the lender using the stablecoin from the offer
        IERC20(offer.stablecoin).safeTransfer(
            msg.sender,
            offer.depositedAmount
        );

        offer.status = OfferStatus.Withdrawn;

        emit OfferWithdrawn(offerId, msg.sender);
    }

    /**
     * @dev Internal function to refund all active offers for a bill request
     * @param billRequestId ID of the bill request
     */
    function _refundAllOffers(uint256 billRequestId) internal {
        uint256[] memory offerIds = billRequestOffers[billRequestId];
        for (uint256 i = 0; i < offerIds.length; i++) {
            uint256 offerId = offerIds[i];
            Offer storage offer = offers[offerId];
            if (offer.status == OfferStatus.Active) {
                // Refund the lender using the stablecoin from the offer
                IERC20(offer.stablecoin).safeTransfer(
                    offer.lender,
                    offer.depositedAmount
                );
                offer.status = OfferStatus.Expired;
            }
        }
    }

    /**
     * @dev Withdraw funds from pool (only admin)
     * @param amount Amount to withdraw
     * @param stablecoin Address of stablecoin
     */
    function withdrawFromPool(
        uint256 amount,
        address stablecoin
    ) external onlyAuthorizedAdmin nonReentrant {
        require(amount > 0, "Amount must be greater than 0");
        require(
            stablecoin == address(USDC) || stablecoin == address(USDT),
            "Unsupported stablecoin"
        );
        require(
            poolBalances[stablecoin] >= amount,
            "Insufficient pool balance"
        );

        poolBalances[stablecoin] -= amount;
        totalPoolBalance -= amount;

        IERC20(stablecoin).safeTransfer(msg.sender, amount);

        emit PoolWithdraw(msg.sender, amount, stablecoin);
    }

    /**
     * @dev Get bills owned by an address
     * @param _owner Address of the bill owner
     * @return Array of bill IDs
     */
    function getBillsByOwner(
        address _owner
    ) external view returns (uint256[] memory) {
        return ownerBills[_owner];
    }

    /**
     * @dev Get bill request details
     * @param billRequestId ID of the bill request
     * @return BillRequest struct
     */
    function getBillRequest(
        uint256 billRequestId
    ) external view returns (BillRequest memory) {
        require(
            billRequests[billRequestId].id != 0,
            "Bill request does not exist"
        );
        return billRequests[billRequestId];
    }

    /**
     * @dev Get offer details
     * @param offerId ID of the offer
     * @return Offer struct
     */
    function getOffer(uint256 offerId) external view returns (Offer memory) {
        require(offers[offerId].id != 0, "Offer does not exist");
        return offers[offerId];
    }

    /**
     * @dev Get offers for a bill request
     * @param billRequestId ID of the bill request
     * @return Array of offer IDs
     */
    function getOffersForBillRequest(
        uint256 billRequestId
    ) external view returns (uint256[] memory) {
        return billRequestOffers[billRequestId];
    }

    /**
     * @dev Get bill details by NFT ID
     * @param nftId ID of the NFT (same as bill ID)
     * @return Bill struct
     */
    function getBillByNFT(uint256 nftId) external view returns (Bill memory) {
        require(_ownerOf(nftId) != address(0), "NFT does not exist");
        require(bills[nftId].id != 0, "Bill does not exist");
        return bills[nftId];
    }

    /**
     * @dev Get bill details
     * @param billId ID of the bill
     * @return Bill struct
     */
    function getBill(uint256 billId) external view returns (Bill memory) {
        require(bills[billId].id != 0, "Bill does not exist");
        return bills[billId];
    }

    /**
     * @dev Get pool balance for a specific stablecoin
     * @param stablecoin Address of stablecoin
     * @return Balance amount
     */
    function getPoolBalance(
        address stablecoin
    ) external view returns (uint256) {
        return poolBalances[stablecoin];
    }

    /**
     * @dev Get current default conditions
     * @return Default conditions struct
     */
    function getDefaultConditions() external view returns (Conditions memory) {
        return defaultConditions;
    }

    /**
     * @dev Get current NFT owner of a bill/bill request
     * @param tokenId ID of the token (bill request ID or bill ID)
     * @return Address of the current NFT owner
     */
    function getBillNFTOwner(uint256 tokenId) external view returns (address) {
        require(_ownerOf(tokenId) != address(0), "NFT does not exist");
        return ownerOf(tokenId);
    }

    /**
     * @dev Get complete bill information including current NFT owner
     * @param billId ID of the bill
     * @return bill The bill struct
     * @return currentOwner Current owner of the NFT
     */
    function getBillWithOwner(
        uint256 billId
    ) external view returns (Bill memory bill, address currentOwner) {
        require(bills[billId].id != 0, "Bill does not exist");
        bill = bills[billId];
        currentOwner = ownerOf(billId);
        return (bill, currentOwner);
    }

    /**
     * @dev Emergency pause function
     */
    function pause() external onlyAuthorizedAdmin {
        _pause();
    }

    /**
     * @dev Unpause function
     */
    function unpause() external onlyAuthorizedAdmin {
        _unpause();
    }

    /**
     * @dev Override required by Solidity for multiple inheritance
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view override returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    /**
     * @dev Override _update to handle bill ownership tracking
     * @param to New owner address (zero address for burns)
     * @param tokenId ID of the token being transferred
     * @param auth Address authorized to perform the update
     */
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address) {
        address from = super._update(to, tokenId, auth);

        // Update ownerBills mapping for transfers (not mints/burns)
        if (from != address(0) && to != address(0)) {
            // This is a transfer, update the mappings
            UintArrayManager.removeFromArray(ownerBills[from], tokenId);
            UintArrayManager.addToArray(ownerBills[to], tokenId);
        }
        // Note: Mints are handled in createBillRequest, burns are handled in completeBill

        return from;
    }
}

contracts/SimpleFund.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {Authorized} from "@privylabs/authorized/contracts/Authorized.sol";
import {FactoringContract} from "./FactoringContract.sol";

/**
 * @title SimpleFund
 * @dev A simplified fund contract that acts as a solo investor for the FactoringContract
 *
 * Key Features:
 * - Solo investor model - no multiple investors to manage
 * - Only authorized wallets can deposit/withdraw funds
 * - Automated bill request and offer creation
 * - Management fees for the contract
 * - Withdrawal functions for upfront payments and debtor payments
 * - Integration with FactoringContract for seamless operations
 */
contract SimpleFund is ReentrancyGuard, Pausable, Authorized, IERC721Receiver {
    using SafeERC20 for IERC20;

    // Reference to the FactoringContract
    FactoringContract public immutable factoringContract;

    // Supported stablecoins
    IERC20 public immutable USDC;
    IERC20 public immutable USDT;

    // Fund configuration
    struct FundConfig {
        uint256 managementFeePercentage; // Management fee percentage (basis points)
        bool acceptingDeposits; // Whether fund is accepting new deposits
    }

    // State variables
    FundConfig public fundConfig;

    mapping(uint256 => bool) public activeBillRequests; // Bill request ID => active
    mapping(uint256 => uint256) public billRequestToOffer; // Bill request ID => offer ID

    // Events
    event FundsDeposited(
        address indexed depositor,
        uint256 amount,
        address token
    );
    event FundsWithdrawn(
        address indexed withdrawer,
        uint256 amount,
        address token
    );
    event OfferCreatedAutomatically(
        uint256 indexed billRequestId,
        uint256 indexed offerId,
        uint256 amount
    );

    event BillRequestFunded(
        uint256 indexed billRequestId,
        address indexed debtor,
        uint256 amount
    );
    event BillCompleted(uint256 indexed billId, uint256 totalReturn);
    event FundConfigUpdated();
    event OfferConfigUpdated();
    event OfferWithdrawn(
        uint256 indexed offerId,
        uint256 indexed billRequestId,
        uint256 amount
    );

    constructor(
        address _factoringContract,
        address _usdc,
        address _usdt,
        FundConfig memory _fundConfig
    ) {
        require(_factoringContract != address(0), "Invalid factoring contract");
        require(_usdc != address(0), "Invalid USDC address");
        require(_usdt != address(0), "Invalid USDT address");

        factoringContract = FactoringContract(_factoringContract);
        USDC = IERC20(_usdc);
        USDT = IERC20(_usdt);

        fundConfig = _fundConfig;
    }

    /**
     * @dev Deposit funds into the contract (only authorized)
     * @param amount Amount to deposit
     * @param token Token address (USDC or USDT)
     */
    function deposit(
        uint256 amount,
        address token
    ) external onlyAuthorizedOperator nonReentrant whenNotPaused {
        require(fundConfig.acceptingDeposits, "Fund not accepting deposits");
        require(amount > 0, "Amount must be greater than 0");
        require(
            token == address(USDC) || token == address(USDT),
            "Unsupported token"
        );

        // Transfer tokens to fund
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        emit FundsDeposited(msg.sender, amount, token);
    }

    /**
     * @dev Withdraw funds from the contract (only authorized)
     * @param amount Amount to withdraw
     * @param token Token to withdraw
     */
    function withdraw(
        uint256 amount,
        address token
    ) external onlyAuthorizedAdmin nonReentrant {
        require(amount > 0, "Amount must be greater than 0");
        require(
            token == address(USDC) || token == address(USDT),
            "Unsupported token"
        );
        require(
            IERC20(token).balanceOf(address(this)) >= amount,
            "Insufficient balance"
        );

        // Transfer tokens to caller
        IERC20(token).safeTransfer(msg.sender, amount);

        emit FundsWithdrawn(msg.sender, amount, token);
    }

    /**
     * @dev Create bill request (SimpleFund acts as debtor)
     * @param totalAmount Total bill amount
     * @param dueDate Due date for the bill
     */
    function createBillRequestForDebtor(
        uint256 totalAmount,
        uint256 dueDate
    )
        external
        onlyAuthorizedOperator
        nonReentrant
        whenNotPaused
        returns (uint256)
    {
        require(totalAmount > 0, "Amount must be greater than 0");

        // Create bill request with fund as debtor (no stablecoin specified)
        uint256 billRequestId = factoringContract.createBillRequest(
            totalAmount,
            dueDate
        );

        emit BillRequestFunded(billRequestId, address(this), totalAmount);

        return billRequestId;
    }

    /**
     * @dev Automatically create offer for bill requests
     * @param billRequestId ID of the bill request
     * @param stablecoin Address of stablecoin to use for the offer
     * @param conditions Offer conditions
     */
    function createOfferForBillRequest(
        uint256 billRequestId,
        address stablecoin,
        FactoringContract.Conditions memory conditions
    ) external onlyAuthorizedOperator nonReentrant whenNotPaused {
        require(
            stablecoin == address(USDC) || stablecoin == address(USDT),
            "Unsupported stablecoin"
        );

        // Get bill request details
        FactoringContract.BillRequest memory billRequest = factoringContract
            .getBillRequest(billRequestId);
        require(billRequest.id != 0, "Bill request does not exist");
        require(uint256(billRequest.status) == 0, "Bill request not open"); // 0 = BillRequestStatus.Open

        // Calculate required upfront amount
        uint256 upfrontAmount = (billRequest.totalAmount *
            conditions.upfrontPercentage) / factoringContract.BASIS_POINTS();
        require(
            IERC20(stablecoin).balanceOf(address(this)) >= upfrontAmount,
            "Insufficient fund balance"
        );

        // Approve FactoringContract to spend our tokens for the offer
        IERC20(stablecoin).approve(address(factoringContract), upfrontAmount);

        // Create the offer and funds are transferred
        uint256 offerId = factoringContract.createOffer(
            billRequestId,
            stablecoin,
            conditions
        );

        // Track the mapping
        billRequestToOffer[billRequestId] = offerId;

        emit OfferCreatedAutomatically(billRequestId, offerId, upfrontAmount);
    }

    /**
     * @dev Accept an offer for a bill request that the fund owns
     * @param offerId ID of the offer to accept
     */
    function acceptOfferForOwnedBill(
        uint256 offerId
    ) external onlyAuthorizedOperator nonReentrant {
        // Get the offer details
        FactoringContract.Offer memory offer = factoringContract.getOffer(
            offerId
        );
        require(offer.id != 0, "Offer does not exist");
        require(uint256(offer.status) == 0, "Offer not active"); // 0 = OfferStatus.Active

        // Check that the fund owns the NFT for this bill request
        address nftOwner = factoringContract.ownerOf(offer.billRequestId);
        require(nftOwner == address(this), "Fund does not own the NFT");
        // Accept the offer
        factoringContract.acceptOffer(offerId);
    }

    /**
     * @dev Withdraw an active offer that the fund created
     * @param offerId ID of the offer to withdraw
     */
    function withdrawOffer(
        uint256 offerId
    ) external onlyAuthorizedOperator nonReentrant {
        // Get the offer details to verify it belongs to this fund
        FactoringContract.Offer memory offer = factoringContract.getOffer(
            offerId
        );
        require(offer.id != 0, "Offer does not exist");
        require(
            offer.lender == address(this),
            "Fund is not the lender for this offer"
        );
        require(uint256(offer.status) == 0, "Offer not active"); // 0 = OfferStatus.Active

        // Withdraw the offer from FactoringContract (this will refund the tokens)
        factoringContract.withdrawOffer(offerId);

        emit OfferWithdrawn(
            offerId,
            offer.billRequestId,
            offer.depositedAmount
        );
    }

    /**
     * @dev Pay a bill on behalf of a debtor
     * @param billId ID of the bill to pay
     */
    function payBillForDebtor(uint256 billId) external nonReentrant {
        // Get bill details
        FactoringContract.Bill memory bill = factoringContract.getBill(billId);
        require(bill.id != 0, "Bill does not exist");
        require(bill.debtor == address(this), "Fund is not the debtor");
        require(
            uint256(bill.status) == 0,
            "Bill not open for payment" // 0 = BillStatus.Open
        );
        // Check if this contract does have the balance in the bill stablecoin
        require(
            getFundBalance(bill.stablecoin) >= bill.totalAmount,
            "Insufficient fund balance"
        );
        // Approve FactoringContract to spend our tokens for bill completion
        IERC20(bill.stablecoin).approve(
            address(factoringContract),
            bill.totalAmount
        );

        // Complete the bill payment
        factoringContract.completeBill(billId);
    }

    /**
     * @dev Withdraw management fees (only owner)
     * @param token Token to withdraw fees in
     */
    function withdrawManagementFees(
        address token
    ) external onlyOwner nonReentrant {
        require(
            token == address(USDC) || token == address(USDT),
            "Unsupported token"
        );

        /// calculate the fundConfig fees to transfer
        uint256 feesToWithdraw = (getFundBalance(token) *
            fundConfig.managementFeePercentage) / factoringContract.BASIS_POINTS();
        require(feesToWithdraw > 0, "No fees to withdraw");

        IERC20(token).safeTransfer(msg.sender, feesToWithdraw);
    }

    /**
     * @dev Withdraw all funds of a specific stablecoin (only owner)
     * @param stablecoin Stablecoin address (USDC or USDT)
     * @param receiver Address to receive the withdrawn funds
     */
    function withdrawAll(
        address stablecoin,
        address receiver
    ) external onlyOwner nonReentrant {
        require(
            stablecoin == address(USDC) || stablecoin == address(USDT),
            "Unsupported stablecoin"
        );
        require(receiver != address(0), "Invalid receiver address");

        // Get actual balance from the stablecoin contract
        uint256 actualBalance = IERC20(stablecoin).balanceOf(address(this));
        require(actualBalance > 0, "No balance to withdraw");

        // Transfer all funds to receiver
        IERC20(stablecoin).safeTransfer(receiver, actualBalance);

        emit FundsWithdrawn(receiver, actualBalance, stablecoin);
    }

    /**
     * @dev Withdraw upfront payment received when an offer is accepted (only owner/admin)
     * @param billId ID of the bill to withdraw upfront payment for
     * @param receiver Address to receive the withdrawn funds
     */
    function withdrawUpfrontPayment(
        uint256 billId,
        address receiver
    ) external onlyAuthorizedAdmin nonReentrant {
        require(receiver != address(0), "Invalid receiver address");

        // Get bill details
        FactoringContract.Bill memory bill = factoringContract.getBill(billId);
        require(bill.id != 0, "Bill does not exist");
        require(bill.debtor == address(this), "Fund is not the debtor");
        require(
            uint256(bill.status) == 0,
            "Bill not active" // 0 = BillStatus.Active
        );

        // Calculate upfront payment amount after debtor fees
        uint256 debtorFee = (bill.upfrontPaid * bill.debtorFeePercentage) /
            factoringContract.BASIS_POINTS();
        uint256 upfrontPaymentAfterFees = bill.upfrontPaid - debtorFee;

        // Verify we have sufficient balance
        require(
            IERC20(bill.stablecoin).balanceOf(address(this)) >=
                upfrontPaymentAfterFees,
            "Insufficient balance for upfront payment withdrawal"
        );

        // Transfer the upfront payment after fees to receiver
        IERC20(bill.stablecoin).safeTransfer(receiver, upfrontPaymentAfterFees);

        emit FundsWithdrawn(receiver, upfrontPaymentAfterFees, bill.stablecoin);
    }

    /**
     * @dev Withdraw debtor payment received when a bill is completed (only owner/admin)
     * @param billId ID of the completed bill to withdraw debtor payment for
     * @param receiver Address to receive the withdrawn funds
     */
    function withdrawDebtorPayment(
        uint256 billId,
        address receiver
    ) external onlyAuthorizedAdmin nonReentrant {
        require(receiver != address(0), "Invalid receiver address");

        // Get bill details
        FactoringContract.Bill memory bill = factoringContract.getBill(billId);
        require(bill.id != 0, "Bill does not exist");
        require(bill.debtor == address(this), "Fund is not the debtor");
        require(
            uint256(bill.status) == 1,
            "Bill not completed" // 1 = BillStatus.Completed
        );

        // Calculate debtor payment using the same logic as FactoringContract.completeBill
        uint256 lenderFees = (bill.upfrontPaid * bill.lenderFeePercentage) /
            factoringContract.BASIS_POINTS();

        // Calculate interest based on days passed
        uint256 daysPassed = (block.timestamp - bill.startDate) / 1 days;
        uint256 interest = (bill.upfrontPaid *
            bill.conditions.rateInterest *
            daysPassed) /
            factoringContract.numberofDaysPerMonth() /
            factoringContract.BASIS_POINTS();

        // Calculate owner payment (lender receives this)
        uint256 ownerPayment = bill.upfrontPaid + interest - lenderFees;

        // Ensure ownerPayment does not exceed totalPayment (same logic as FactoringContract)
        if (ownerPayment > bill.totalAmount) {
            ownerPayment = bill.totalAmount - lenderFees;
        }

        // Calculate debtor payment (what debtor gets back)
        uint256 debtorPayment = bill.totalAmount - ownerPayment;

        // Only proceed if there's a debtor payment to withdraw
        require(debtorPayment > 0, "No debtor payment available");

        // Verify we have sufficient balance
        require(
            IERC20(bill.stablecoin).balanceOf(address(this)) >= debtorPayment,
            "Insufficient balance for debtor payment withdrawal"
        );

        // Transfer the debtor payment to receiver
        IERC20(bill.stablecoin).safeTransfer(receiver, debtorPayment);

        emit FundsWithdrawn(receiver, debtorPayment, bill.stablecoin);
    }

    /**
     * @dev Update fund configuration (only authorized admin)
     * @param newConfig New fund configuration
     */
    function updateFundConfig(
        FundConfig memory newConfig
    ) external onlyAuthorizedAdmin {
        fundConfig = newConfig;
        emit FundConfigUpdated();
    }

    // Removed updateOfferConfig and offerConfig state variable, as offer config is now passed as parameters

    /**
     * @dev Get total fund balance for a specific token
     * @param token Token address
     * @return Token balance
     */
    function getFundBalance(address token) public view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    /**
     * @dev Get total fund value across all tokens
     * @return Total fund value
     */
    function getTotalFundValue() public view returns (uint256) {
        return getFundBalance(address(USDC)) + getFundBalance(address(USDT));
    }

    /**
     * @dev Pause the contract (only authorized admin)
     */
    function pause() external onlyAuthorizedAdmin {
        _pause();
    }

    /**
     * @dev Unpause the contract (only authorized admin)
     */
    function unpause() external onlyAuthorizedAdmin {
        _unpause();
    }

    /**
     * @dev Handle NFT transfers (ERC721Receiver implementation)
     */
    function onERC721Received(
        address /* operator */,
        address /* from */,
        uint256 /* tokenId */,
        bytes calldata /* data */
    ) external pure override returns (bytes4) {
        return this.onERC721Received.selector;
    }
}

